class Solution {
public:
    vector<int> maximumSubarrayXor(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<vector<int>> g(n, vector<int>(n)), best(n, vector<int>(n));
        for (int i = 0; i < n; i++) g[i][i] = best[i][i] = nums[i];
        for (int len = 2; len <= n; len++)
            for (int l = 0; l + len - 1 < n; l++) {
                int r = l + len - 1;
                g[l][r] = g[l][r - 1] ^ g[l + 1][r];
                best[l][r] = max({g[l][r], best[l + 1][r], best[l][r - 1]});
            }
        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& q : queries) ans.push_back(best[q[0]][q[1]]);
        return ans;
    }
};

