                cur[l] = prev[l] ^ prev[l + 1];
                best[l][r] = max({cur[l], best[l + 1][r], best[l][r - 1]});
            }
            prev.swap(cur);
        }
        vector<int> ans;
        for (auto& q : queries) ans.push_back(best[q[0]][q[1]]);
