                best[l][r] = Math.max(cur[l], Math.max(best[l + 1][r], best[l][r - 1]));
            }
            prev = cur;
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) ans[i] = best[queries[i][0]][queries[i][1]];
        return ans;
